_QUOTES,'UTF-8')?></h3><?php foreach(['code'=>'Modello','name'=>'Nome','cooling_kw'=>'Raffrescamento (kW)','seer'=>'SEER','seer_class'=>'Classe SEER','heating_kw'=>'Riscaldamento (kW)','scop'=>'SCOP','scop_class'=>'Classe SCOP','indoor_unit_code'=>'Codice UI','outdoor_unit_code'=>'Codice UE'] as $field=>$label):?><label><?=$label?><input name="<?=$field?>" value="<?=htmlspecialchars((string)($m[$field]??''),ENT_QUOTES,'UTF-8')?>" <?=$field==='code'?'required':''?>></label><?php endforeach;?><label>Ordine<input type="number" name="sort_order" value="<?=(int)$m['sort_order']?>"></label><label>Stato<select name="content_status"><?php foreach(['published'=>'Pubblicato','draft'=>'Bozza','hidden'=>'Nascosto'] as $value=>$label):?><option value="<?=$value?>" <?=($m['content_status']??($m['published']?'published':'hidden'))===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><div class="full"><button class="btn">Salva variante</button></div></form><?php endforeach;?></div><form method="post" action="/idemaclima/admin/products/delete" onsubmit="return confirm('Eliminare definitivamente questo prodotto? Se esistono collegamenti l’operazione verrà bloccata.')"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$product['id'] ?>"><button class="danger" type="submit">Elimina prodotto</button></form><?php endif; ?>
